"""Markdown report for benchmark results."""

from __future__ import annotations

from pathlib import Path

from .metrics import BenchmarkReport


def render_markdown(report: BenchmarkReport) -> str:
    memory = report.aggregate(report.results)
    baseline = report.aggregate(report.baseline_results)
    lines: list[str] = [
        "# Engram Benchmark Report",
        "",
        (
            "> Generated by `python -m engram.benchmark`. "
            "All numbers are produced by the local deterministic configuration "
            "(hash embeddings + heuristic extraction)."
        ),
        "",
        "## Summary",
        "",
        "| Metric | Memory | Full-history baseline |",
        "|---|---:|---:|",
        f"| Scenarios | {memory['scenarios']} | {baseline['scenarios']} |",
        f"| Scenarios passed | {memory['scenarios_passed']} | {baseline['scenarios_passed']} |",
        f"| Checks passed | {memory['checks_passed']}/{memory['checks']} | {baseline['checks_passed']}/{baseline['checks']} |",
        f"| Check pass rate | {memory['check_pass_rate']:.2%} | {baseline['check_pass_rate']:.2%} |",
        f"| Expected hit rate | {memory['expected_hit_rate']:.2%} | {baseline['expected_hit_rate']:.2%} |",
        f"| Forbidden hit rate | {memory['forbidden_hit_rate']:.2%} | {baseline['forbidden_hit_rate']:.2%} |",
        f"| Avg hits | {memory['avg_hits']:.2f} | {baseline['avg_hits']:.2f} |",
        f"| Avg tokens | {memory['avg_tokens']:.1f} | {baseline['avg_tokens']:.1f} |",
        "",
        "## By category",
        "",
        "| Category | Memory passed | Total |",
        "|---|---:|---:|",
    ]
    for category, bucket in sorted(memory["by_category"].items()):
        lines.append(f"| {category} | {bucket['passed']} | {bucket['total']} |")

    if report.ablations:
        lines.extend(
            [
                "",
                "## Ablations",
                "",
                "| Condition | Scenarios passed | Checks passed | Forbidden hit rate |",
                "|---|---:|---:|---:|",
            ]
        )
        for name, results in report.ablations.items():
            aggregate = report.aggregate(results)
            lines.append(
                f"| {name} | {aggregate['scenarios_passed']}/{aggregate['scenarios']} | "
                f"{aggregate['checks_passed']}/{aggregate['checks']} | "
                f"{aggregate['forbidden_hit_rate']:.2%} |"
            )

    lines.extend(
        [
            "",
            "## Scenarios",
            "",
            "| Scenario | Category | Passed | Conflicts | Memories |",
            "|---|---|---:|---:|---:|",
        ]
    )
    for result in report.results:
        lines.append(
            f"| {result.scenario_id} | {result.category} | "
            f"{'yes' if result.passed else 'no'} | {result.conflict_count} | {result.memory_count} |"
        )

    failures = [
        (result, check)
        for result in report.results
        for check in result.checks
        if not check.passed
    ]
    lines.extend(["", "## Failures", ""])
    if not failures:
        lines.append("No failures.")
    else:
        for result, check in failures:
            lines.append(f"### {result.scenario_id} / {check.query}")
            lines.append("")
            lines.append(f"- hits: {check.hits} (min_ok={check.min_hits_ok}, max_ok={check.max_hits_ok})")
            if check.missing:
                lines.append(f"- missing: {', '.join(check.missing)}")
            if check.forbidden:
                lines.append(f"- forbidden: {', '.join(check.forbidden)}")
            if check.context_preview:
                lines.append(f"- context: `{check.context_preview[:300]}`")
            lines.append("")

    lines.extend(
        [
            "",
            "## Notes",
            "",
            (
                "- The full-history baseline puts every user turn into the context. "
                "It can pass factual checks but fails on stale/contradictory facts and privacy."
            ),
            (
                "- The memory condition uses hybrid retrieval, conflict supersede, "
                "sensitivity filtering and a token budget."
            ),
            (
                "- These scenarios are a development benchmark, not a substitute for "
                "a human-annotated, held-out evaluation."
            ),
        ]
    )
    return "\n".join(lines) + "\n"


def write_markdown_report(report: BenchmarkReport, path: str | Path) -> Path:
    output = Path(path)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(render_markdown(report), encoding="utf-8")
    return output
